declare(strict_types=1); require dirname(__DIR__) . '/app/core/bootstrap.php'; require_role('technician'); $tickets=(new Ticket($pdo))->forTechnician((int) current_user()['id']); require dirname(__DIR__) . '/app/views/layout.php'; page_header('Assigned tickets');
